Here's a complete implementation of a **small Electron app** that maintains a **to-do list in a JSON file**, using:

- `contextIsolation: true` (for security)
- `preload.js` to expose a secure API via `contextBridge`
- `main.js` to handle file operations and IPC
- `renderer.js` to interact with the UI and communicate with `main.js`

---

### 📁 Project Structure

```
todo-app/
├── main.js
├── preload.js
├── renderer.js
└── todos.json
```

---

## 1. `main.js`

Handles file operations and IPC communication.

```js
// main.js
const { app, BrowserWindow, ipcMain, dialog } = require('electron');
const fs = require('fs');
const path = require('path');

const TODOS_FILE = path.join(__dirname, 'todos.json');

// Ensure todos.json exists
if (!fs.existsSync(TODOS_FILE)) {
  fs.writeFileSync(TODOS_FILE, JSON.stringify([]));
}

function createWindow() {
  const win = new BrowserWindow({
    width: 600,
    height: 400,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  win.loadFile('index.html');
}

app.whenReady().then(createWindow);

// Handle IPC requests
ipcMain.handle('get-todos', async () => {
  const data = fs.readFileSync(TODOS_FILE, 'utf-8');
  return JSON.parse(data);
});

ipcMain.handle('save-todos', async (event, todos) => {
  fs.writeFileSync(TODOS_FILE, JSON.stringify(todos, null, 2));
});
```

---

## 2. `preload.js`

Exposes a secure API to the renderer using `contextBridge`.

```js
// preload.js
const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('todoAPI', {
  getTodos: () => ipcRenderer.invoke('get-todos'),
  saveTodos: (todos) => ipcRenderer.invoke('save-todos', todos),
});
```

---

## 3. `renderer.js`

Handles UI logic and interacts with the main process.

```js
// renderer.js
document.addEventListener('DOMContentLoaded', () => {
  const input = document.getElementById('todo-input');
  const addBtn = document.getElementById('add-btn');
  const todoList = document.getElementById('todo-list');

  // Load todos on startup
  window.todoAPI.getTodos().then(todos => {
    renderTodos(todos);
  });

  addBtn.addEventListener('click', () => {
    const text = input.value.trim();
    if (text) {
      const todos = window.todoAPI.getTodos();
      todos.push({ text, completed: false });
      window.todoAPI.saveTodos(todos);
      renderTodos(todos);
      input.value = '';
    }
  });

  function renderTodos(todos) {
    todoList.innerHTML = '';
    todos.forEach((todo, index) => {
      const li = document.createElement('li');
      li.textContent = todo.text;
      if (todo.completed) li.style.textDecoration = 'line-through';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;
      checkbox.onchange = () => {
        const updated = todos.map(t => (t === todo ? { ...t, completed: checkbox.checked } : t));
        window.todoAPI.saveTodos(updated);
        renderTodos(updated);
      };
      li.appendChild(checkbox);
      li.appendChild(document.createTextNode(' ' + todo.text));
      todoList.appendChild(li);
    });
  }
});
```

---

## 4. `index.html`

Basic HTML structure for the renderer.

```html
<!-- index.html -->
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Todo List</title>
</head>
<body>
  <h1>Todo List</h1>
  <input id="todo-input" type="text" placeholder="Add a new task" />
  <button id="add-btn">Add</button>
  <ul id="todo-list"></ul>

  <script src="renderer.js"></script>
</body>
</html>
```

---

## ✅ How to Run

1. Make sure you have Electron installed:
   ```bash
   npm install electron --save-dev
   ```

2. Add a start script in `package.json`:
   ```json
   "scripts": {
     "start": "electron ."
   }
   ```

3. Run the app:
   ```bash
   npm start
   ```

---

## 🔒 Security Notes

- `contextIsolation: true` ensures that Node.js APIs are not directly accessible from the renderer.
- `contextBridge` is used to expose only necessary APIs.
- File operations are handled securely in the main process.

